// ---------------------------------------------------------------------------
// Rf_asReal — scalar double extractor from a SEXP.
//
// Corresponds to Rinternals.h line 488:
//   double Rf_asReal(SEXP x);
// with alias at Rinternals.h line 910:
//   #define asReal  Rf_asReal
//
// Implementation strategy (Category B — inline accessor):
//   - For REALSXP input (the primary type for all rpart call sites):
//     cast s->data to double * and return element [0].  This is the
//     direct read used in both CSV usage locations.
//   - For INTSXP input (not observed in rpart CSV subset, but handled
//     for correctness per asReal.md Section 3 safety recommendation):
//     cast s->data to int * and widen element [0] to double, matching
//     real Rf_asReal coercion semantics for integer scalars.
//   - For all other SEXPTYPE values: fall through to the double * cast.
//
// SEXP.h already defined Rf_asReal (basic form, double-cast only) and
// asReal (inline wrapper) under FAKE_ASINTEGER_DEFINED.  Because C++
// disallows redefining an inline function with a different body in the
// same translation unit, the INTSXP-coercing implementation is provided
// as Rf_asReal_coerce() for completeness.  The SEXP.h basic form is
// functionally correct for all rpart call sites (all arguments are
// length-1 REALSXP constructed by the Python caller).
//
// Pattern P1 coverage (rpartexp2.c:48):
//   Rpartexp2(n, REAL(dtimes), asReal(eps), INTEGER(keep));
//   asReal(eps) expands to Rf_asReal(eps), which returns:
//     static_cast<double *>(eps->data)[0]
//   The result is the first (and only) element of the eps REALSXP,
//   passed directly as the third argument to Rpartexp2(int n,
//   double *y, double eps, int *keep).
//
// Pattern P2 coverage (xpred.c:76):
//   toprisk = asReal(toprisk2);
//   asReal(toprisk2) expands to Rf_asReal(toprisk2), which returns:
//     static_cast<double *>(toprisk2->data)[0]
//   The result is assigned to the local variable 'double toprisk'
//   declared earlier in xpred().  toprisk is used in subsequent
//   computation in the xpred function body.
// ---------------------------------------------------------------------------
#ifndef FAKE_ASREAL_FULL_DEFINED
#define FAKE_ASREAL_FULL_DEFINED

// Full implementation with INTSXP coercion branch.
// Named Rf_asReal_coerce to avoid redefinition conflict with SEXP.h's
// simpler Rf_asReal inline.  Provides explicit INTSXP->double widening
// for callers that need the full coercion semantics (not used by rpart).
inline double Rf_asReal_coerce(SEXP s) {
    // INTSXP coercion branch: widen int element [0] to double.
    // Matches real Rf_asReal behavior for integer-typed scalars.
    // Not observed in rpart's CSV usage sites (all inputs are REALSXP),
    // but included for correctness per asReal.md Section 3.
    if (s->type == INTSXP)
        return static_cast<double>(static_cast<int *>(s->data)[0]);
    // REALSXP (and all other types): read double element [0] directly.
    // Both rpart usage locations (rpartexp2.c:48, xpred.c:76) pass
    // REALSXP scalars; this is the primary execution path.
    return static_cast<double *>(s->data)[0];
}

// Note: Rf_asReal (the canonical name) is already defined as an inline
// by SEXP.h under the FAKE_ASINTEGER_DEFINED guard:
//   inline double Rf_asReal(SEXP s) { return ((double *) s->data)[0]; }
// The basic form is correct for all rpart call sites.  Rf_asReal_coerce
// is available for use cases requiring the INTSXP safety branch.

#endif // FAKE_ASREAL_FULL_DEFINED

// ---------------------------------------------------------------------------
// --- Compatibility aliases (preserve original R API names) ---
//
// Original Rinternals.h alias (line 910):
//   #define asReal  Rf_asReal
//
// SEXP.h provides asReal as an inline function (not a macro), so macro
// expansion is not strictly needed if SEXP.h was included first.
// However, if this header is included in a translation unit without
// SEXP.h, the macro alias must be present so that every occurrence of
// asReal(...) in the rpart source compiles correctly.
//
// The #ifndef guard prevents redefinition if SEXP.h's inline function
// is already present.  Since SEXP.h uses inline functions rather than
// macros for asReal, the #ifndef asReal test will be TRUE (macros and
// function names do not conflict in the preprocessor), so the #define
// is safe to emit.  It maps asReal -> Rf_asReal, which resolves to
// SEXP.h's inline function (double-cast, correct for REALSXP scalars).
// ---------------------------------------------------------------------------

// Preserve the original Rinternals.h alias: #define asReal Rf_asReal
// (Rinternals.h line 910).  SEXP.h provides asReal as an inline function;
// if that inline is visible, this #define is redundant but harmless — the
// compiler resolves 'asReal(x)' to either the macro (Rf_asReal(x)) or
// the inline, both of which reach the same implementation.
#ifndef asReal
#define asReal Rf_asReal
#endif

// ---------------------------------------------------------------------------
// Python-side construction note for asReal callers:
//
// Every SEXP passed to asReal in rpart's source is a length-1 REALSXP
// scalar constructed by the Python caller before the .Call boundary.
// Python must allocate a SEXPREC with:
//   s->type   = REALSXP  (14)
//   s->length = 1
//   s->nrow   = 1
//   s->ncol   = 1
//   s->data   = pointer to a single double holding the value
//
// Example (Python ctypes, assuming SEXPREC is exposed):
//   def make_real_sexp(value: float) -> ctypes.POINTER(SEXPREC):
//       node = SEXPREC()
//       node.type   = REALSXP       # 14
//       node.length = 1
//       node.nrow   = 1
//       node.ncol   = 1
//       buf = (ctypes.c_double * 1)(value)
//       node.data = ctypes.cast(buf, ctypes.c_void_p)
//       return ctypes.pointer(node)
//
// Usage at rpartexp2.c:48 (Pattern P1):
//   eps_sexp = make_real_sexp(1e-6)
//   # asReal(eps_sexp) -> Rf_asReal(eps_sexp) -> eps_sexp->data[0] == 1e-6
//   # passed as third argument to Rpartexp2(..., 1e-6, ...)
//
// Usage at xpred.c:76 (Pattern P2):
//   toprisk2_sexp = make_real_sexp(0.05)
//   # toprisk = asReal(toprisk2_sexp) -> toprisk2_sexp->data[0] == 0.05
//   # stored in local variable toprisk for later computation in xpred()
//
// Once passed to asReal(), the function returns buf[0] as a plain C double.
// The Python caller retains ownership of buf and node; both can be freed
// after the .Call entry-point returns.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
